#!/usr/bin/env bash
set -euo pipefail
du -xhd1 "${1:-/}" 2>/dev/null | sort -h | tail -n 20

#!/usr/bin/env bash
set -euo pipefail
URL="${1:-https://example.com}"
CODE=$(curl -s -o /dev/null -w "%{http_code}" --max-time 10 "$URL" || echo 000)
[[ "$CODE" =~ ^[23] ]] && echo "OK $CODE" || { echo "FAIL $CODE"; exit 1; }
